// @pit: {"label": "Check outdated npm deps and latest action/pit releases"}
async ({ shell: { exec } }) => {
  const [od, rel] = await Promise.all([
    exec("npm outdated --json; true", { timeoutMs: 120000 }),
    exec(`for r in actions/checkout actions/setup-node actions/create-github-app-token cv/pit; do echo "$r: $(gh api repos/$r/releases/latest --jq '.tag_name' 2>&1)"; done; gh api repos/actions/create-github-app-token/git/ref/tags/$(gh api repos/actions/create-github-app-token/releases/latest --jq .tag_name) --jq '.object' ; gh api repos/cv/pit/releases/tags/v0.39.0 --jq .body | head -60; gh api repos/cv/pit/releases/tags/v0.38.0 --jq .body 2>&1| head -40`, { timeoutMs: 60000 }),
  ]);
  return { od: od.stdout, rel: rel.stdout, err: rel.stderr };
}
